(function() {
    'use strict';

    class NexoCoworkingAdapter extends USF.SimulationAdapter {
        constructor() {
            super();
            this.name = 'Business & Strategy Primer: El Negocio Completo';
            this.version = '2.0.0';

            // Willingness-to-pay bands (CLP thousands/month), monthly churn %, facility prefs, per-period gross acquisitions, NPS baseline.
            this.SEGMENTS = {
                freelancers: { wtpLow: 72, wtpHigh: 90,  baseChurn: 10, prefFacility: 'comfort',    prefFacility2: 'technology',      baseDemand: 20, npsBase: 0 },
                corporate:   { wtpLow: 100, wtpHigh: 130, baseChurn: 3,  prefFacility: 'private',    prefFacility2: 'technology',      baseDemand: 14, npsBase: 5 },
                startups:    { wtpLow: 85,  wtpHigh: 115, baseChurn: 5,  prefFacility: 'technology', prefFacility2: 'comfort',         baseDemand: 13, npsBase: 3 },
                students:    { wtpLow: 60,  wtpHigh: 78,  baseChurn: 15, prefFacility: 'comfort',    prefFacility2: 'sustainability',  baseDemand: 20, npsBase: -5 }
            };

            // Incremental monthly delivery cost by service level (added on top of the base overhead).
            this.SERVICE_COSTS = { basic: 0, standard: 500000, premium: 1100000 };
            this.SERVICE_NPS = { basic: 0, standard: 8, premium: 18 };
            this.SERVICE_CHURN_REDUCTION = { basic: 0, standard: 1.5, premium: 3 };

            // Incremental monthly staffing cost (added on top of base founder overhead).
            this.STAFFING_COSTS = { none: 0, assistant: 600000, manager: 1200000 };
            this.STAFFING_SERVICE_MULT = { none: 0.8, assistant: 1.0, manager: 1.2 };

            // One-time (per-period) initiative costs.
            this.INITIATIVE_COSTS = { referral: 500000, university: 1000000, certification: 1500000, virtual: 800000, popup: 6000000 };

            // Base fixed overhead (rent, utilities, admin, founder) — CLP/month. Everything else is incremental.
            this.BASE_OP_COST = 2850000;
            // Variable cost-to-serve per active member per month (utilities, coffee, cleaning, support).
            // This is the concept's core loop: more members -> higher operating cost per customer -> margin pressure.
            this.VARIABLE_PER_MEMBER = 18000;
            // Facilities capital budget per 6-month period (concept §Round-1: allocate CLP 5,000,000/round).
            this.FACILITIES_BUDGET = 5000000;
            this.START_CAPACITY = 95;   // hot-desking: 48 workstations serve up to ~95 members (58 => 61% at start).
            this.MONTHS_PER_PERIOD = 6;
            this.CHURN_MONTHS = 3;      // effective within-period churn exposure (members hold ~semester terms).

            this.ROUNDS = [
                { titleKey: 'round1_title', descKey: 'round1_desc', event: null },
                { titleKey: 'round2_title', descKey: 'round2_desc', event: 'lease_renewal' },
                { titleKey: 'round3_title', descKey: 'round3_desc', event: 'anchor_tenant' }
            ];

            // Fields restored from the per-period base snapshot so calculateResults is idempotent (B4).
            this._SNAPSHOT_FIELDS = [
                'cash', 'members', 'capacity', 'nps', 'facilitiesQuality', 'serviceConsistency',
                'staffSatisfaction', 'previousSegment', 'structure', 'referralActive', 'referralRoundsLeft',
                'certificationActive', 'virtualMembership', 'universityPartner', 'popupOpen',
                'leaseChoice', 'anchorChoice'
            ];
        }

        initialize(state) {
            if (!state.domainState || Object.keys(state.domainState).length === 0) {
                state.domainState = {
                    cash: 3600000,
                    monthlyRevenue: 5800000,
                    monthlyOpCost: 5200000,
                    members: 58,
                    capacity: this.START_CAPACITY,
                    occupancy: 61,
                    nps: 34,
                    churn: 8,
                    ebitda: 600000,
                    ebitdaMargin: 10.3,
                    facilitiesQuality: 50,
                    serviceConsistency: 50,
                    staffSatisfaction: 50,
                    coherenceScore: 0,
                    totalScore: 0,
                    primarySegment: null,
                    previousSegment: null,
                    structure: 'simple',
                    referralActive: false,
                    referralRoundsLeft: 0,
                    certificationActive: false,
                    virtualMembership: false,
                    universityPartner: false,
                    popupOpen: false,
                    leaseChoice: null,
                    anchorChoice: null,
                    currentEvent: null,
                    baseByPeriod: {},
                    revenueHistory: [],
                    ebitdaHistory: [],
                    marginHistory: [],
                    npsHistory: [],
                    occupancyHistory: [],
                    churnHistory: [],
                    coherenceHistory: [],
                    cashHistory: [],
                    pnlHistory: []
                };
            }
            if (!state.decisions || Object.keys(state.decisions).length === 0) {
                state.decisions = {
                    segment: 'freelancers',
                    price: 95,
                    facilities: 'balanced',
                    serviceLevel: 'standard',
                    staffing: 'none',
                    training: false,
                    initiative: 'referral',
                    eventResponse: ''
                };
            }
            this._updateBriefing(state);
        }

        validateDecisions(decisions) {
            var segEl = document.getElementById('segmentSelect');
            if (segEl) decisions.segment = segEl.value;

            var priceEl = document.getElementById('priceInput');
            if (priceEl) decisions.price = parseFloat(priceEl.value);

            var facEl = document.getElementById('facilitiesSelect');
            if (facEl) decisions.facilities = facEl.value;

            var svcEl = document.getElementById('serviceSelect');
            if (svcEl) decisions.serviceLevel = svcEl.value;

            var staffEl = document.getElementById('staffingSelect');
            if (staffEl) decisions.staffing = staffEl.value;

            var trainEl = document.getElementById('trainingCheck');
            if (trainEl) decisions.training = trainEl.checked;

            var initEl = document.getElementById('initiativeSelect');
            if (initEl) decisions.initiative = initEl.value;

            var evtEl = document.getElementById('eventResponseSelect');
            if (evtEl && document.getElementById('eventResponsePanel').style.display !== 'none') {
                decisions.eventResponse = evtEl.value;
            } else {
                decisions.eventResponse = '';
            }

            if (isNaN(decisions.price) || decisions.price < 60 || decisions.price > 140) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('price_warning'), 'warning'
                );
                return false;
            }

            var currentState = window.mySimulation.state;
            var roundIdx = (currentState.currentPeriod || 1) - 1;
            var round = this.ROUNDS[Math.min(roundIdx, this.ROUNDS.length - 1)];
            if (round.event && !decisions.eventResponse) {
                window.mySimulation.uiManager.showNotification(
                    window.mySimulation.t('event_required'), 'warning'
                );
                return false;
            }

            this._updateBriefing(window.mySimulation.state);
            return true;
        }

        // ---- idempotency helpers (B4) ----
        _snapshotBase(ds, period) {
            var key = 'p' + period;
            if (!ds.baseByPeriod) ds.baseByPeriod = {};
            if (!ds.baseByPeriod[key]) {
                var snap = {};
                for (var i = 0; i < this._SNAPSHOT_FIELDS.length; i++) {
                    var f = this._SNAPSHOT_FIELDS[i];
                    snap[f] = ds[f];
                }
                ds.baseByPeriod[key] = snap;
            } else {
                var s = ds.baseByPeriod[key];
                for (var k in s) { if (s.hasOwnProperty(k)) ds[k] = s[k]; }
            }
        }

        calculateResults(state) {
            var d = state.decisions;
            var ds = state.domainState;
            var seg = this.SEGMENTS[d.segment];
            var period = state.currentPeriod;
            var priceK = d.price;

            // Restore begin-of-period base so re-computing the same period is idempotent (B4).
            this._snapshotBase(ds, period);

            var segmentChanged = (ds.previousSegment !== null && ds.previousSegment !== d.segment);
            ds.previousSegment = d.segment;

            // ---- price fit vs segment willingness-to-pay ----
            var priceFit;
            if (priceK >= seg.wtpLow && priceK <= seg.wtpHigh) {
                priceFit = 1.0;
            } else if (priceK < seg.wtpLow) {
                priceFit = Math.min(1.15, 1.0 + (seg.wtpLow - priceK) / 100); // underpricing lifts demand modestly
            } else {
                var over = priceK - seg.wtpHigh;
                priceFit = Math.max(0.25, 1.0 - (over / 40));
            }

            var facilityFit = 0.6;
            if (d.facilities === seg.prefFacility) facilityFit = 1.0;
            else if (d.facilities === seg.prefFacility2) facilityFit = 0.85;
            else if (d.facilities === 'balanced') facilityFit = 0.75;

            var serviceMult = this.STAFFING_SERVICE_MULT[d.staffing] || 0.8;
            var serviceEffect = (this.SERVICE_NPS[d.serviceLevel] || 0) * serviceMult;

            // ---- WeXpand competitive pressure (deterministic, from R2) ----
            if (period >= 2) {
                ds.wexpandPrice = 105;
                if (d.segment === 'corporate' && priceK > 105) {
                    priceFit *= 0.9;
                }
            }

            // ---- gross new acquisitions this period ----
            var newDemand = seg.baseDemand * priceFit * facilityFit;
            if (ds.referralActive && ds.referralRoundsLeft <= 0) newDemand += 5;
            if (ds.universityPartner && d.segment === 'students') newDemand += 12;
            if (ds.certificationActive && d.segment === 'corporate') newDemand += 6;
            if (ds.virtualMembership) newDemand += 5;
            if (ds.popupOpen) newDemand += 8; // second location draws additional demand (B5)
            if (segmentChanged) newDemand *= 0.7;
            newDemand = Math.round(newDemand);

            // ---- deterministic events (B3) ----
            var eventCost = 0;
            ds.currentEvent = null;

            // Viral negative review: overcharging for a bare-bones service is punished, deterministically.
            var viralReview = (d.serviceLevel === 'basic' && priceK >= 100);
            if (viralReview) { ds.currentEvent = 'viral'; eventCost += 1200000; }

            // Espacio Libre (cheapest competitor) closes in R3 — scripted opportunity, not random.
            if (period === 3) {
                ds.currentEvent = ds.currentEvent || 'competitor';
                if (d.segment === 'freelancers' || d.segment === 'students') newDemand += 10;
                else newDemand += 4;
            }

            // ---- churn -> 6-month retention (compounded monthly rate) ----
            var churnRate = seg.baseChurn;
            churnRate -= (this.SERVICE_CHURN_REDUCTION[d.serviceLevel] || 0);
            if (d.training) churnRate -= 0.5;
            if (ds.certificationActive) churnRate -= 0.5;
            if (segmentChanged) churnRate += 4;
            churnRate = Math.max(1, churnRate);

            var retention = Math.pow(1 - churnRate / 100, this.CHURN_MONTHS);
            var retained = ds.members * retention;

            // ---- anchor tenant (R3) expands dedicated-desk capacity and adds guaranteed members ----
            var anchorDesks = 0;
            if (period === 3) {
                if (d.eventResponse === 'accept_full') anchorDesks = 15;
                else if (d.eventResponse === 'accept_partial') anchorDesks = 8;
            }
            ds.capacity = this.START_CAPACITY + (ds.popupOpen ? 20 : 0) + anchorDesks;

            var totalMembers = Math.round(retained + newDemand + anchorDesks);
            totalMembers = Math.max(5, Math.min(ds.capacity, totalMembers));
            ds.members = totalMembers;

            ds.occupancy = Math.min(100, Math.round((totalMembers / ds.capacity) * 100));

            // ---- revenue ----
            var monthlyRev = totalMembers * priceK * 1000;
            // Anchor corporate tenants pay at least a corporate rate regardless of list price.
            if (anchorDesks > 0) {
                var anchorRate = Math.max(priceK, 110) * 1000;
                monthlyRev += anchorDesks * Math.max(0, anchorRate - priceK * 1000);
            }
            var periodRevenue = monthlyRev * this.MONTHS_PER_PERIOD;
            ds.monthlyRevenue = monthlyRev;

            // ---- costs (base overhead + incremental choices) ----
            var baseOpCost = this.BASE_OP_COST;
            if (ds.leaseChoice === 'long') baseOpCost = Math.round(baseOpCost * 1.15);
            if (ds.popupOpen) baseOpCost += 1200000; // second-location fixed cost (B5 cash-flow risk)

            var periodBaseCost = baseOpCost * this.MONTHS_PER_PERIOD;
            var variableCost = Math.round(totalMembers * this.VARIABLE_PER_MEMBER * this.MONTHS_PER_PERIOD); // cost-to-serve
            var serviceCost = (this.SERVICE_COSTS[d.serviceLevel] || 0) * this.MONTHS_PER_PERIOD;
            var staffCost = (this.STAFFING_COSTS[d.staffing] || 0) * this.MONTHS_PER_PERIOD;
            var trainingCost = d.training ? 800000 : 0;
            var facilitiesCost = this.FACILITIES_BUDGET;
            var initiativeCost = this.INITIATIVE_COSTS[d.initiative] || 0;
            var anchorInvest = (d.eventResponse === 'accept_full') ? 8000000 : (d.eventResponse === 'accept_partial' ? 4000000 : 0);
            if (period !== 3) anchorInvest = 0;

            var totalCost = periodBaseCost + variableCost + serviceCost + staffCost + trainingCost + facilitiesCost + initiativeCost + anchorInvest + eventCost;

            var ebitdaOperating = periodRevenue - (totalCost - anchorInvest - initiativeCost); // EBITDA excludes one-time capex for margin display
            var ebitda = periodRevenue - totalCost;
            var monthlyEbitda = Math.round(ebitdaOperating / this.MONTHS_PER_PERIOD);
            var ebitdaMargin = periodRevenue > 0 ? Math.round((ebitdaOperating / periodRevenue) * 1000) / 10 : 0;

            ds.ebitda = monthlyEbitda;
            ds.ebitdaMargin = ebitdaMargin;
            ds.monthlyOpCost = Math.round((totalCost - anchorInvest - initiativeCost) / this.MONTHS_PER_PERIOD);
            ds.cash += ebitda;

            // ---- NPS ----
            var nps = ds.nps;
            var npsChange = 0;
            npsChange += seg.npsBase;
            npsChange += (facilityFit >= 0.85 ? 5 : (facilityFit >= 0.7 ? 0 : -5));
            npsChange += serviceEffect;
            if (d.facilities === 'sustainability') npsChange += 5;
            if (d.training) npsChange += 3;
            if (segmentChanged) npsChange -= 8;
            if (viralReview) npsChange -= 12;
            if (ds.certificationActive) npsChange += 3;
            nps = Math.max(-100, Math.min(100, nps + npsChange));
            ds.nps = Math.round(nps);

            ds.churn = Math.round(churnRate * 10) / 10;

            // ---- BSC internal-process & growth metrics ----
            var fq = ds.facilitiesQuality;
            if (d.facilities === 'technology') fq += 12;
            else if (d.facilities === 'comfort') fq += 10;
            else if (d.facilities === 'private') fq += 10;
            else if (d.facilities === 'sustainability') fq += 6;
            else fq += 8;
            ds.facilitiesQuality = Math.round(Math.min(100, fq));

            var sc = ds.serviceConsistency;
            sc += (this.SERVICE_NPS[d.serviceLevel] || 0);
            sc *= serviceMult;
            if (d.training) sc += 5;
            ds.serviceConsistency = Math.round(Math.max(0, Math.min(100, sc)));

            var ss = ds.staffSatisfaction;
            if (d.training) ss += 8;
            if (d.staffing === 'manager') ss += 5;
            else if (d.staffing === 'assistant') ss += 2;
            else ss -= 3;
            if (d.serviceLevel === 'premium' && d.staffing === 'none') ss -= 10;
            ds.staffSatisfaction = Math.round(Math.max(0, Math.min(100, ss)));

            ds.structure = (d.staffing === 'manager') ? 'functional' : 'simple';

            // ---- initiatives (persist) ----
            if (d.initiative === 'referral') { ds.referralActive = true; ds.referralRoundsLeft = Math.max(0, 2 - period); }
            if (d.initiative === 'university') ds.universityPartner = true;
            if (d.initiative === 'certification') ds.certificationActive = true;
            if (d.initiative === 'virtual') ds.virtualMembership = true;
            if (d.initiative === 'popup') ds.popupOpen = true;

            if (period === 2 && d.eventResponse) ds.leaseChoice = d.eventResponse;
            if (period === 3 && d.eventResponse) ds.anchorChoice = d.eventResponse;

            var coherence = this._calcCoherence(d, seg);
            ds.coherenceScore = coherence;

            // ---- write history BY INDEX (idempotent, B4) ----
            var idx = period - 1;
            ds.revenueHistory[idx] = ds.monthlyRevenue;
            ds.ebitdaHistory[idx] = ds.ebitda;
            ds.marginHistory[idx] = ds.ebitdaMargin;
            ds.npsHistory[idx] = ds.nps;
            ds.occupancyHistory[idx] = ds.occupancy;
            ds.churnHistory[idx] = ds.churn;
            ds.coherenceHistory[idx] = coherence;
            ds.cashHistory[idx] = ds.cash;
            ds.pnlHistory[idx] = {
                period: period,
                revenue: periodRevenue,
                baseCost: periodBaseCost,
                variableCost: variableCost,
                serviceCost: serviceCost,
                staffCost: staffCost,
                facilitiesCost: facilitiesCost,
                trainingCost: trainingCost,
                initiativeCost: initiativeCost,
                anchorInvest: anchorInvest,
                eventCost: eventCost,
                ebitda: ebitda,
                margin: ebitdaMargin
            };

            var totalScoreVal = this._calcTotalScore(ds);
            ds.totalScore = totalScoreVal;

            var results = {
                period: period,
                segment: d.segment,
                price: d.price,
                facilities: d.facilities,
                serviceLevel: d.serviceLevel,
                staffing: d.staffing,
                initiative: d.initiative,
                members: ds.members,
                occupancy: ds.occupancy,
                monthlyRevenue: ds.monthlyRevenue,
                ebitda: ds.ebitda,
                ebitdaMargin: ds.ebitdaMargin,
                nps: ds.nps,
                churn: ds.churn,
                coherence: coherence,
                totalScore: totalScoreVal,
                cash: ds.cash
            };

            // Refresh briefing/debrief from the REAL post-advance state, once the framework has advanced (U3).
            var self = this;
            setTimeout(function() {
                if (window.mySimulation && window.mySimulation.state) {
                    self._updateBriefing(window.mySimulation.state);
                }
            }, 0);

            return results;
        }

        _calcCoherence(d, seg) {
            var score = 0;
            var priceK = d.price;
            if (priceK >= seg.wtpLow && priceK <= seg.wtpHigh) score += 5;
            else if (Math.abs(priceK - seg.wtpLow) <= 10 || Math.abs(priceK - seg.wtpHigh) <= 10) score += 3;
            else score += 1;

            if (d.facilities === seg.prefFacility) score += 5;
            else if (d.facilities === seg.prefFacility2) score += 3;
            else if (d.facilities === 'balanced') score += 2;
            else score += 1;

            var svcScore;
            if (d.serviceLevel === 'premium' && priceK >= 100) svcScore = 5;
            else if (d.serviceLevel === 'standard' && priceK >= 80 && priceK <= 115) svcScore = 5;
            else if (d.serviceLevel === 'basic' && priceK <= 85) svcScore = 5;
            else if (d.serviceLevel === 'premium' && priceK >= 85) svcScore = 3;
            else if (d.serviceLevel === 'basic' && priceK >= 100) svcScore = 1;
            else svcScore = 2;
            score += svcScore;

            var initFit = 1;
            if (d.initiative === 'referral') initFit = 3;
            if (d.initiative === 'university' && d.segment === 'students') initFit = 5;
            else if (d.initiative === 'university') initFit = 2;
            if (d.initiative === 'certification' && d.segment === 'corporate') initFit = 5;
            else if (d.initiative === 'certification' && d.segment === 'startups') initFit = 4;
            else if (d.initiative === 'certification') initFit = 2;
            if (d.initiative === 'virtual') initFit = 3;
            if (d.initiative === 'popup' && (d.segment === 'freelancers' || d.segment === 'startups')) initFit = 4;
            else if (d.initiative === 'popup') initFit = 2;
            score += initFit;

            return Math.min(20, score);
        }

        _calcTotalScore(ds) {
            var marginScore;
            var m = ds.ebitdaMargin;
            if (m >= 25) marginScore = 25;
            else if (m >= 15) marginScore = 20;
            else if (m >= 10) marginScore = 15;
            else if (m >= 5) marginScore = 10;
            else if (m >= 0) marginScore = 5;
            else marginScore = 0;

            var occScore;
            var o = ds.occupancy;
            if (o >= 90) occScore = 20;
            else if (o >= 80) occScore = 16;
            else if (o >= 70) occScore = 12;
            else if (o >= 60) occScore = 8;
            else occScore = 4;

            var npsScore;
            var n = ds.nps;
            if (n >= 60) npsScore = 20;
            else if (n >= 45) npsScore = 16;
            else if (n >= 30) npsScore = 12;
            else if (n >= 15) npsScore = 8;
            else npsScore = 4;

            var coherenceScore = ds.coherenceScore;

            var churnScore;
            var c = ds.churn;
            if (c <= 3) churnScore = 15;
            else if (c <= 5) churnScore = 12;
            else if (c <= 7) churnScore = 9;
            else if (c <= 10) churnScore = 6;
            else churnScore = 3;

            return marginScore + occScore + npsScore + coherenceScore + churnScore;
        }

