        getPerformanceSummary(history) {
            if (!history.length) return {};
            var t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return k; };
            var lastResult = history[history.length - 1].results || {};
            var totalScore = lastResult.totalScore || 0;
            var avgOccupancy = history.reduce(function(s, r) { return s + (r.results ? r.results.occupancy : 0); }, 0) / history.length;

            var perfKey = 'perf_risk', insightKey = 'insight_risk';
            if (totalScore >= 85) { perfKey = 'perf_strategic'; insightKey = 'insight_strategic'; }
            else if (totalScore >= 70) { perfKey = 'perf_competent'; insightKey = 'insight_competent'; }
            else if (totalScore >= 55) { perfKey = 'perf_transition'; insightKey = 'insight_transition'; }

            return {
                totalScore: totalScore,
                ebitdaMargin: lastResult.ebitdaMargin,
                avgOccupancy: Math.round(avgOccupancy),
                finalNps: lastResult.nps || 0,
                coherence: lastResult.coherence || 0,
                performance: t(perfKey),
                rating: t(perfKey),
                average: totalScore,
                insights: [t(insightKey)]
            };
        }

