        _segmentName(segKey) {
            var map = {
                en: { freelancers: 'Freelancers & Creatives', corporate: 'Corporate Remote Workers', startups: 'Startups & Small Business', students: 'University Students' },
                es: { freelancers: 'Freelancers y Creativos', corporate: 'Trabajadores Remotos Corporativos', startups: 'Startups y Pequeñas Empresas', students: 'Estudiantes Universitarios' }
            };
            var lang = (window.mySimulation && window.mySimulation.lang) ? window.mySimulation.lang : 'en';
            return (map[lang] || map.en)[segKey] || segKey;
        }

        _updateBriefing(state) {
            var t = (window.mySimulation && window.mySimulation.t) ? function(k){ return window.mySimulation.t(k); } : function(k){ return ''; };
            var maxP = (state.maxPeriods || this.ROUNDS.length);

            // End of game -> render debrief instead of a round briefing (U1/U3).
            if ((state.currentPeriod || 1) > maxP) {
                this._renderDebrief(state);
                return;
            }

            var idx = Math.min((state.currentPeriod || 1) - 1, this.ROUNDS.length - 1);
            var round = this.ROUNDS[idx];

            var titleEl = document.getElementById('briefingTitle');
            if (titleEl) { var tt = t(round.titleKey); if (tt) titleEl.innerHTML = tt; }
            var descEl = document.getElementById('briefingText');
            if (descEl) { var dt = t(round.descKey); if (dt) descEl.innerHTML = dt; }

            var eventResponsePanel = document.getElementById('eventResponsePanel');
            var eventResponseSelect = document.getElementById('eventResponseSelect');
            var eventResponseLabel = document.getElementById('eventResponseLabel');

            if (round.event && eventResponsePanel && eventResponseSelect) {
                eventResponsePanel.style.display = 'block';
                eventResponseSelect.innerHTML = '';
                var opts = [];
                if (round.event === 'lease_renewal') {
                    if (eventResponseLabel) eventResponseLabel.innerHTML = t('lease_event_label');
                    opts = [['long', t('lease_long')], ['short', t('lease_short')]];
                } else if (round.event === 'anchor_tenant') {
                    if (eventResponseLabel) eventResponseLabel.innerHTML = t('anchor_event_label');
                    opts = [['accept_full', t('anchor_full')], ['accept_partial', t('anchor_partial')], ['decline', t('anchor_decline')]];
                }
                for (var i = 0; i < opts.length; i++) {
                    var o = document.createElement('option');
                    o.value = opts[i][0];
                    o.textContent = opts[i][1];
                    eventResponseSelect.appendChild(o);
                }
            } else if (eventResponsePanel) {
                eventResponsePanel.style.display = 'none';
            }

            // Event banner reflects ONLY the most recent round's event (U2).
            var eventPanel = document.getElementById('eventPanel');
            var evt = state.domainState ? state.domainState.currentEvent : null;
            if (eventPanel) {
                if (evt) {
                    eventPanel.style.display = 'block';
                    var et = document.getElementById('eventTitle');
                    var ed = document.getElementById('eventDescription');
                    if (et) et.innerHTML = t('evt_' + evt + '_title');
                    if (ed) ed.innerHTML = t('evt_' + evt + '_desc');
                } else {
                    eventPanel.style.display = 'none';
                }
            }
        }

        _renderDebrief(state) {
            var panel = document.getElementById('debriefPanel');
            if (!panel) return;
            var t = function(k){ return window.mySimulation.t(k); };
            var ds = state.domainState;
            var hist = (window.mySimulation.history || []);
            var summary = this.getPerformanceSummary(hist);

            // Hide the round briefing + event panels once the game is over.
            var bp = document.getElementById('briefingPanel'); if (bp) bp.style.display = 'none';
            var ep = document.getElementById('eventPanel'); if (ep) ep.style.display = 'none';

            var html = '';
            html += '<h3>' + t('debrief_title') + '</h3>';
            html += '<p class="nexo-debrief-verdict"><strong>' + (summary.performance || '') + '</strong> — ' + t('debrief_score') + ': <strong>' + (summary.totalScore || 0) + ' / 100</strong></p>';
            html += '<p>' + ((summary.insights && summary.insights[0]) || '') + '</p>';

            // Income statement (F1)
            html += '<h4>' + t('pnl_title') + '</h4>';
            html += '<div class="nexo-table-wrap"><table class="table table-sm nexo-pnl"><thead><tr>' +
                '<th>' + t('pnl_period') + '</th><th>' + t('pnl_revenue') + '</th><th>' + t('pnl_costs') + '</th><th>' + t('pnl_investments') + '</th><th>' + t('pnl_ebitda') + '</th><th>' + t('pnl_margin') + '</th>' +
                '</tr></thead><tbody>';
            var fmt = function(v) { return 'CLP $' + Math.round(v).toLocaleString(); };
            (ds.pnlHistory || []).forEach(function(p) {
                if (!p) return;
                var opCosts = p.baseCost + (p.variableCost || 0) + p.serviceCost + p.staffCost + p.facilitiesCost + p.trainingCost + p.eventCost;
                var invest = (p.initiativeCost || 0) + (p.anchorInvest || 0);
                html += '<tr><td>R' + p.period + '</td><td>' + fmt(p.revenue) + '</td><td>' + fmt(opCosts) + '</td><td>' + fmt(invest) + '</td>' +
                    '<td class="' + (p.ebitda >= 0 ? 'nexo-pos' : 'nexo-neg') + '">' + fmt(p.ebitda) + '</td><td>' + p.margin.toFixed(1) + '%</td></tr>';
            });
            html += '</tbody></table></div>';

            // Business Model Canvas before/after (F3)
            var seg = ds.previousSegment || 'freelancers';
            var afterCosts = 'CLP $' + Math.round(ds.monthlyOpCost).toLocaleString() + '/mo';
            var afterRes = t('canvas_start_resources') + (ds.popupOpen ? ' + pop-up' : '') + (ds.anchorChoice && ds.anchorChoice !== 'decline' ? ' + anchor desks' : '');
            html += '<h4>' + t('canvas_title') + '</h4>';
            html += '<div class="nexo-canvas-grid">' +
                '<div class="nexo-canvas-col"><div class="nexo-canvas-head">' + t('canvas_before') + '</div>' +
                    this._canvasRow(t('canvas_segment'), t('canvas_start_segment')) +
                    this._canvasRow(t('canvas_value'), t('canvas_start_value')) +
                    this._canvasRow(t('canvas_resources'), t('canvas_start_resources')) +
                    this._canvasRow(t('canvas_costs'), t('canvas_start_costs')) +
                    this._canvasRow(t('canvas_coherence'), '0 / 20') +
                '</div>' +
                '<div class="nexo-canvas-col nexo-canvas-after"><div class="nexo-canvas-head">' + t('canvas_after') + '</div>' +
                    this._canvasRow(t('canvas_segment'), this._segmentName(seg)) +
                    this._canvasRow(t('canvas_value'), this._segmentName(seg) + ' · NPS ' + (ds.nps >= 0 ? '+' : '') + ds.nps) +
                    this._canvasRow(t('canvas_resources'), afterRes) +
                    this._canvasRow(t('canvas_costs'), afterCosts) +
                    this._canvasRow(t('canvas_coherence'), ds.coherenceScore + ' / 20') +
                '</div></div>';

            panel.innerHTML = html;
                 panel.style.display = 'block';
        }

        _canvasRow(label, val) {
            return '<div class="nexo-canvas-row"><span class="nexo-canvas-label">' + label + '</span><span class="nexo-canvas-val">' + val + '</span></div>';
        }
    }

    document.addEventListener('DOMContentLoaded', function() {
        window.mySimulation = new USF.SimulationFramework();
        window.mySimulation.initialize(new NexoCoworkingAdapter(), {
            simulationType: 'nexo_coworking_290',
            maxPeriods: 3,
            autoSaveInterval: 30000
        });
    });

